public String getPrefix(String uri) throws SAXException {
    String prefix = namespaces.get(uri);
    if (prefix != null) {
        return prefix;
    } else if (parent != null) {
        return parent.getPrefix(uri);
    } else if (uri == null || uri.isEmpty()) {
        return "";
    } else {
        throw new SAXException("Namespace " + uri + " not declared");
    }
}
